-- KANEL × ALCEDO bookings — S110 PREFLIGHT (READ-ONLY). Run immediately before the
-- S110 apply bundle; keep the output. GENERATED by scripts/release/generate_kanel_s110_release.py.
-- Go only if there is no FAIL row; every WARN row needs an explicit owner decision.
with live as (
  select r.id, r.booking_reference, r.party_size, r.start_at,
         pg_catalog.array_agg(rt.table_id) as seats,
         pg_catalog.sum(t.seat_capacity)::int as capacity
  from atlas_private.reservations r
  join atlas_private.reservation_tables rt on rt.reservation_id = r.id and rt.released_at is null
  join atlas_private.booking_tables t on t.id = rt.table_id
  where r.status in ('confirmed','arrived','seated') and r.end_at > pg_catalog.now()
  group by r.id
)
select section, "check", status, detail from (
select 1 as ord, 'ledger' as section, 'production is at S109' as "check",
  case when (select max(version) from supabase_migrations.schema_migrations) = '20261026090000' then 'PASS' else 'FAIL' end as status,
  'last migration ' || coalesce((select max(version) from supabase_migrations.schema_migrations), 'none') as detail
union all select 2, 'ledger', 'no S110 row yet',
  case when not exists (select 1 from supabase_migrations.schema_migrations where version = '20261027090000') then 'PASS' else 'FAIL' end, ''
union all select 3, * from (select * from (select 'drift', 'booking_table_json body = S109',
  case when (select pg_catalog.md5(p.prosrc) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'atlas_private' and p.proname = 'booking_table_json' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_table_id uuid') = 'fe7747ff55f7c973520b3b75d894ddda' then 'PASS' else 'FAIL' end,
  coalesce((select 'md5 ' || pg_catalog.md5(p.prosrc) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'atlas_private' and p.proname = 'booking_table_json' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_table_id uuid'), 'function missing')) x union all select * from (select 'drift', 'booking_table_json grants = S109',
  case when (select coalesce(p.proacl::text, '') = '{postgres=X/postgres,service_role=X/postgres}' from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'atlas_private' and p.proname = 'booking_table_json' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_table_id uuid') then 'PASS' else 'FAIL' end,
  coalesce((select coalesce(p.proacl::text, '') from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'atlas_private' and p.proname = 'booking_table_json' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_table_id uuid'), 'function missing')) x union all select * from (select 'drift', 'atlas_bookings_assign body = S109',
  case when (select pg_catalog.md5(p.prosrc) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_bookings_assign' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_actor_id uuid, p_actor_role text, p_reservation_id uuid, p_table_ids jsonb') = '9485d77fe5c5568cc6d8282f2dc05990' then 'PASS' else 'FAIL' end,
  coalesce((select 'md5 ' || pg_catalog.md5(p.prosrc) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_bookings_assign' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_actor_id uuid, p_actor_role text, p_reservation_id uuid, p_table_ids jsonb'), 'function missing')) x union all select * from (select 'drift', 'atlas_bookings_assign grants = S109',
  case when (select coalesce(p.proacl::text, '') = '{postgres=X/postgres,service_role=X/postgres}' from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_bookings_assign' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_actor_id uuid, p_actor_role text, p_reservation_id uuid, p_table_ids jsonb') then 'PASS' else 'FAIL' end,
  coalesce((select coalesce(p.proacl::text, '') from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_bookings_assign' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_actor_id uuid, p_actor_role text, p_reservation_id uuid, p_table_ids jsonb'), 'function missing')) x union all select * from (select 'drift', 'atlas_bookings_create body = S109',
  case when (select pg_catalog.md5(p.prosrc) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_bookings_create' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_actor_id uuid, p_actor_role text, p_payload jsonb') = 'c782d63724fa4a914c0fbeb31de5f515' then 'PASS' else 'FAIL' end,
  coalesce((select 'md5 ' || pg_catalog.md5(p.prosrc) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_bookings_create' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_actor_id uuid, p_actor_role text, p_payload jsonb'), 'function missing')) x union all select * from (select 'drift', 'atlas_bookings_create grants = S109',
  case when (select coalesce(p.proacl::text, '') = '{postgres=X/postgres,service_role=X/postgres}' from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_bookings_create' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_actor_id uuid, p_actor_role text, p_payload jsonb') then 'PASS' else 'FAIL' end,
  coalesce((select coalesce(p.proacl::text, '') from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_bookings_create' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_actor_id uuid, p_actor_role text, p_payload jsonb'), 'function missing')) x) d
union all select 4, 'not yet released', 'booking_check_seat_group absent',
  case when not exists (select 1 from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'atlas_private' and p.proname = 'booking_check_seat_group') then 'PASS' else 'FAIL' end, ''
union all select 5, 'settings', 'turnaround / online cap (unchanged by S110)', 'INFO',
  (select 'turnaround ' || turnaround_minutes || ' min, max_party_online ' || max_party_online
     || ', public_online_enabled ' || public_online_enabled from atlas_private.booking_settings where id = true)
union all select 6, 'impact', 'future allocations with fewer seats than guests (could not be re-assigned unchanged)',
  case when exists (select 1 from live where capacity < party_size) then 'WARN' else 'PASS' end,
  coalesce((select string_agg(booking_reference || ' (' || party_size || ' guests, ' || capacity || ' seats)', '; ') from live where capacity < party_size), 'none')
union all select 7, 'impact', 'future multi-seat allocations that are not one adjacent group in one section',
  case when exists (select 1 from live where pg_catalog.cardinality(seats) > 1
                    and not atlas_private.booking_tables_contiguous_segment(seats)) then 'WARN' else 'PASS' end,
  coalesce((select string_agg(booking_reference, '; ') from live where pg_catalog.cardinality(seats) > 1
                    and not atlas_private.booking_tables_contiguous_segment(seats)), 'none')
union all select 8, 'impact', 'future active bookings (all sources)', 'INFO',
  (select pg_catalog.count(*)::text from atlas_private.reservations where start_at > pg_catalog.now()
     and status in ('requested','confirmed','arrived','seated'))
) checks order by ord, "check";
